/**
 * Authentication utility functions for client-side components
 */

/**
 * Safely decodes a URL parameter
 * @param {string} url - The URL to decode
 * @returns {string} - The decoded URL
 */
export const safeDecodeURIComponent = (url) => {
  try {
    return decodeURIComponent(url);
  } catch (error) {
    console.error('Error decoding URL:', error);
    return url;
  }
};

/**
 * Checks if the current URL is a sign-in redirect
 * This helps prevent the sign-in page from showing up during dashboard navigation
 *
 * @returns {boolean} True if the current URL is a sign-in redirect
 */
export const isSignInRedirect = () => {
  if (typeof window === 'undefined') return false;

  const url = window.location.href;
  return url.includes('/sign-in') && url.includes('redirect_url');
};

/**
 * Handles authentication redirects
 * If the user is already authenticated and on the sign-in page, redirect to dashboard
 *
 * @param {Object} router - Next.js router object
 * @param {boolean} isAuthenticated - Whether the user is authenticated
 */
export const handleAuthRedirect = (router, isAuthenticated) => {
  if (typeof window === 'undefined') return;

  const url = window.location.href;

  // If user is authenticated and on sign-in page, redirect to dashboard
  if (isAuthenticated && url.includes('/sign-in')) {
    try {
      // Get the redirect URL from the query parameters or use dashboard as default
      const urlParams = new URLSearchParams(window.location.search);
      let redirectUrl = urlParams.get('redirect_url') || '/dashboard';

      // Safely decode the URL if it's encoded
      redirectUrl = safeDecodeURIComponent(redirectUrl);

      console.log('Auth redirect - redirecting to:', redirectUrl);

      // Ensure the redirect URL is valid
      if (redirectUrl.startsWith('/')) {
        // Internal URL - use router.replace
        router.replace(redirectUrl);
      } else if (redirectUrl.startsWith('http')) {
        // External URL - check if it's to our own domain
        try {
          const currentDomain = window.location.hostname;
          const redirectDomain = new URL(redirectUrl).hostname;

          if (redirectDomain === currentDomain) {
            router.replace(redirectUrl);
          } else {
            console.warn('Attempted redirect to external domain:', redirectUrl);
            router.replace('/dashboard');
          }
        } catch (error) {
          console.error('Error parsing redirect URL:', error);
          router.replace('/dashboard');
        }
      } else {
        // Invalid URL - fallback to dashboard
        console.warn('Invalid redirect URL:', redirectUrl);
        router.replace('/dashboard');
      }
    } catch (error) {
      console.error('Error during auth redirect:', error);
      router.replace('/dashboard');
    }
  }
};

/**
 * Prevents sign-in page from showing during dashboard navigation
 * This function should be called in the useEffect hook of dashboard components
 *
 * @param {Object} router - Next.js router object
 */
export const preventSignInRedirect = (router) => {
  if (typeof window === 'undefined') return;

  const url = window.location.href;

  // If we're on the sign-in page with a redirect URL to dashboard, go directly to dashboard
  if (url.includes('/sign-in') && url.includes('redirect_url=') && url.includes('/dashboard')) {
    router.replace('/dashboard');
  }
};

/**
 * Checks if the current page is an authentication page (sign-in or sign-up)
 *
 * @returns {boolean} True if the current page is an authentication page
 */
export const isAuthPage = () => {
  if (typeof window === 'undefined') return false;

  const url = window.location.href;
  return url.includes('/sign-in') || url.includes('/sign-up');
};

/**
 * Handles post-authentication redirect
 * This function should be called after successful authentication
 *
 * @param {Object} router - Next.js router object
 * @param {string} defaultRedirect - Default redirect URL if no redirect_url is specified
 */
export const handlePostAuthRedirect = (router, defaultRedirect = '/dashboard') => {
  if (typeof window === 'undefined') return;

  try {
    // Get the redirect URL from the query parameters or use default
    const urlParams = new URLSearchParams(window.location.search);
    let redirectUrl = urlParams.get('redirect_url') || defaultRedirect;

    // Safely decode the URL if it's encoded
    redirectUrl = safeDecodeURIComponent(redirectUrl);

    console.log('Post-auth redirect - redirecting to:', redirectUrl);

    // Validate and perform the redirect
    if (redirectUrl.startsWith('/')) {
      router.push(redirectUrl);
    } else {
      console.warn('Invalid redirect URL, using default:', redirectUrl);
      router.push(defaultRedirect);
    }
  } catch (error) {
    console.error('Error during post-auth redirect:', error);
    router.push(defaultRedirect);
  }
};
