"use client";

import { useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@clerk/nextjs';
import AuthRedirect from './AuthRedirect';
import { handleAuthRedirect, handlePostAuthRedirect } from '../../../lib/auth/authUtils';

/**
 * SignInWrapper component
 * Wraps the Clerk SignIn component and handles redirection after successful login
 *
 * @param {Object} props - Component props
 * @param {React.ReactNode} props.children - Child components (Clerk SignIn)
 */
const SignInWrapper = ({ children }) => {
  const router = useRouter();
  const { isLoaded, isSignedIn } = useAuth();

  // Handle redirect when auth state changes
  useEffect(() => {
    if (!isLoaded) return;

    if (isSignedIn) {
      // User is authenticated, redirect to dashboard or specified redirect URL
      handlePostAuthRedirect(router);
    }
  }, [isLoaded, isSignedIn, router]);

  // Use AuthRedirect to handle redirection when user is already authenticated
  return (
    <>
      {/* Redirect to dashboard if already signed in */}
      <AuthRedirect
        redirectTo="/dashboard"
        ifAuthenticated={true}
        forceRedirect={false}
      />

      {/* Show sign-in component */}
      {children}
    </>
  );
};

export default SignInWrapper;
